INSERT INTO public.email_source (id, analyzed_message_ids, event_rules, is_active, target_address, service_provider_id) VALUES ('99ce1f23-1b77-420a-a5e3-987b72ed6f6d', '["190927ce07f9eacf", "195bfc792ee5bcbe", "190926d0cc2f3531", "195ee970f2954eb3", "190820cc8e9fd673"]', '[{"isActive": true, "template": {"snippetRegex": "(\\Q고객님의 취소 요청이 처리되었습니다. 고객님의 서비스가 2025년 03월 31일 (PT)에 종료될 예정입니다. 취소 확인 고객님의 취소 요청이 처리되었습니다. 고객님의 서비스가 2\\E)", "subjectRegex": "(\\Q2025년 03월 31일 (PT)에 서비스 종료 예정\\E)"}, "eventType": "SUBSCRIPTION_CANCEL", "updatedAt": 1768951022.710421400}]', true, 'message@adobe.com', '27daa86b-6adb-45e0-a837-2af4a394ee69');
INSERT INTO public.email_source (id, analyzed_message_ids, event_rules, is_active, target_address, service_provider_id) VALUES ('b6c679db-b1e1-407e-85bd-9f29d793a673', '["1878e46c00da9d9c", "19014110822eae15", "18962e8d7d1a27bd", "18eeb1a9467cd67f", "18ae752872192241", "18a028df5bb0c316", "18f8598119fb43e5", "18db61d55ee2d115", "1865e727c94cc0e0", "18c76d18829201b7", "18ff1c77ff96684d", "18d167b6d08f876c", "188c869cad94abb3", "186eea2c4818cdaa", "1873e27ba4a7a164", "18b3caf3134eb04e", "185dec89ccc165fc", "18fffe1927227419", "185becf0be8bdb2e", "18caff7fcc1fc426", "18ff1c7be4e18cb1", "1901483a2036e020", "18bdc532da5dfead", "18c16fa6fa8842e9", "18aa230a17350152", "18828c7be8492286", "18e4b75a73dc59d0"]', '[{"isActive": true, "template": {"snippetRegex": "(\\Q현2님, 왓챠 이용권이 7일 후에 만료돼요 현2과 함께 했던 시간도 이제 정말 얼마 남지 않았네요. 남은 시간 동안 보고 싶었던 작품 한 편이라도 더 같이 보고 가세요. (보고싶어\\E)|(\\Q한 작품이라도 더 보고 가세요, 현2님. 현2님의 왓챠 구독권이 3일 후 사라져요. 현2님이 떠나지 않기를 바라지만, 그게 이번엔 어렵다면 남은 기간 동안 왓챠를 더욱 즐기고 가시\\E)", "subjectRegex": "(\\Q[WATCHA] 현2님, 우리 이제 7일 밖에 남지 않았어요\\E)|(\\Q[WATCHA] 현2님, 이게 우리의 마지막 메일이에요\\E)"}, "eventType": "SUBSCRIPTION_CANCEL", "updatedAt": 1768951022.710421400}, {"isActive": true, "template": {"snippetRegex": "(\\Q현2님, 왓챠 정기 이용권이 성공적으로 갱신되었습니다! 결제 일시: 2023-01-17 17:18 결제 수단: 카카오페이(자동 결제) 총 결제 금액: [PRICE](VAT 포함) \\E)|(\\Q현2님, 왓챠 정기 이용권이 성공적으로 갱신되었습니다! 결제 일시: 2023-04-17 17:13 결제 수단: 카카오페이(자동 결제) 총 결제 금액: [PRICE](VAT 포함) \\E)|(\\Q현2님, 왓챠 정기 구독권이 성공적으로 갱신되었습니다! 결제 일시: 2024-03-17 17:09 결제 수단: 카카오페이(자동 결제) 총 결제 금액: [PRICE](VAT 포함) \\E)|(\\Q현2님, 왓챠 정기 구독권이 성공적으로 갱신되었습니다! 결제 일시: 2024-05-17 17:08 결제 수단: 카카오페이(자동 결제) 총 결제 금액: [PRICE](VAT 포함) \\E)", "subjectRegex": "(\\Q[WATCHA] 이용권이 성공적으로 갱신되었습니다.\\E)|(\\Q[왓챠] 이용권이 성공적으로 갱신되었습니다.\\E)|(\\Q[왓챠] 구독권이 성공적으로 갱신되었습니다.\\E)|(\\Q[WATCHA] 구독권이 성공적으로 갱신됐어요\\E)"}, "eventType": "MONTHLY_PAYMENT", "updatedAt": 1768951022.710421400}]', true, 'do-not-reply@watcha.com', '13a93b08-2169-41a9-87af-e8b7243d14f5');
INSERT INTO public.email_source (id, analyzed_message_ids, event_rules, is_active, target_address, service_provider_id) VALUES ('298f05f0-b2cd-4816-a3d5-52e8978d4e47', '["18bcb2851c7c4a3a", "199824038cc20c80", "19b633ef8816f70b", "193e2002a7c59048", "19b5eb4d89185432", "19385145406919ed", "193b5a2ee93456f1", "19b5eb36c656f8a3", "18e328fd316e51cf", "19b5eb7b6405f519"]', '[{"isActive": true, "template": {"snippetRegex": "(\\QMelOn 멜론 이용권구매 안내 스트리밍 플러스 정기결제해지 신청 취소가 완료 되었습니다. 무제한 듣기 단, 오프라인일 때는 모바일에서만 무제한 듣기 가능 해지내역 서비스 상태 이\\E)|(\\QMelOn 멜론 이용권구매 안내 스트리밍 플러스 구매 및 멜론 2개월 [PRICE] 프로모션! 참여가 완료 되었습니다. 무제한 듣기 단, 오프라인일 때는 모바일에서만 무제한 듣기 \\E)", "subjectRegex": "(\\Q[멜론] \"스트리밍 플러스\" 해지신청 취소 안내\\E)|(\\Q[멜론] \"스트리밍 플러스\" 구매완료\\E)"}, "eventType": "SUBSCRIPTION_START", "updatedAt": 1768951022.709897800}, {"isActive": true, "template": {"snippetRegex": "(\\QMelOn 멜론 정기결제해지 안내 스트리밍 플러스 정기결제해지 신청이 완료 되었습니다. 무제한 듣기 단, 오프라인일 때는 모바일에서만 무제한 듣기 가능 해지내역 서비스 상태 정기결\\E)|(\\QMelOn 중도해지 신청 안내 스트리밍 플러스 중도해지 신청이 완료 되었습니다. 무제한 듣기 단, 오프라인일 때는 모바일에서만 무제한 듣기 가능 해지내역 서비스 상태 중도해지 완료\\E)", "subjectRegex": "(\\Q[멜론] \"스트리밍 플러스\" 해지신청 완료 안내\\E)|(\\Q[멜론] \"스트리밍 플러스\" 중도해지 신청완료 안내\\E)"}, "eventType": "SUBSCRIPTION_CANCEL", "updatedAt": 1768951022.709897800}]', true, 'noreply_melon@kakaoent.com', '470162c4-1e91-4325-bb7e-feef51c33cb5');
INSERT INTO public.email_source (id, analyzed_message_ids, event_rules, is_active, target_address, service_provider_id) VALUES ('2f5baaa9-e303-4648-99e3-b461aad5e425', '["19b0563f9fc1ad9f", "19813abc202ea678", "19969d763d8bd2ea", "19afee3d6405a29d", "1940d5a407867390", "198dea45c1ceee5c", "19a7da81ced149f2", "1941c992b7c8790d", "198bd1765e6fd2ca", "1942475286870696", "198152ffd480c6c0", "1980d48b0bb69ad3", "19afa4e4cd8bf89f", "19aff780525c0d42", "1980f76fd7599825", "198153271fe48cf1", "19b6be4238e7e822", "1940e8e5a2e2c7d6", "198345658c1d6469", "1994d2d81cb7ee78", "19ab5b9b42b52be9", "198795aac2430c58", "197bc3a30d07e1a5", "19af09644d90c402", "198ece88354c6656", "19b8d1c755422dbc", "19a4195ac997e191", "19911a0681f77cbf", "19954e6af259dad2", "19857fe8c8627744", "19a2922cf8b68ce4", "19813abc3047adb3", "194247419bccd3c3", "198f7c9b9cdfc728", "19ad5fbefb311df3", "19b2960cf0ec03e8", "19b9323aebbcff0a", "19815324d3768811", "19a7be439927efa2", "1948ca756537adce"]', '[{"isActive": true, "template": {"snippetRegex": "(\\Qご利用開始にあたり役立つ情報をご案内します。\\E)|(\\Qこれで、映画やドラマをお楽しみいただける準備が整いました。\\E)|(\\Q업데이트 완료! 회원님의 계정에 새로운 결제 수단 정보가 등록되었습니다.\\E)", "subjectRegex": "(\\QNetflixへようこそ\\E)|(\\Qおかえりなさい!\\E)|(\\Q계정 정보 변경 확인\\E)"}, "eventType": "SUBSCRIPTION_START", "updatedAt": 1768951022.710421400}, {"isActive": true, "template": {"snippetRegex": "(\\Q2025年1月24日までNetflixをお楽しみいただけます\\E)|(\\Q넷플릭스 멤버십을 다시 시작하세요. 쉽고 간단하게!\\E)|(\\Q회원님의 멤버십이 현재 정지되어 있습니다. 도움이 필요하시면 언제든지 고객 센터로 문의해 주시기 바랍니다.\\E)", "subjectRegex": "(\\Qメンバーシップのキャンセルのご案内\\E)|(\\Q회원님의 멤버십이 보류 중입니다\\E)|(\\Q결제 수단을 업데이트해 주세요.\\E)"}, "eventType": "SUBSCRIPTION_CANCEL", "updatedAt": 1768951022.710421400}]', true, 'info@account.netflix.com', 'c620c334-325f-4d6c-aa17-bac4884f9cf8');
